public class BandwidthEstimate {
    public static void main(String[] args) {
        long dau = 1_000_000L;
        long viewsPerUser = 50;
        long photoBytes = 200 * 1024;            // ảnh trong bài viết ~200 KB
        double peakFactor = 3.0;

        long viewsPerDay = dau * viewsPerUser;
        double avgQps = viewsPerDay / 86_400.0;
        double peakQps = avgQps * peakFactor;
        double peakBytesPerSec = peakQps * photoBytes;
        double peakGbps = peakBytesPerSec / 1_000_000_000;

        System.out.printf("Lượt xem/ngày : %,d%n", viewsPerDay);
        System.out.printf("QPS trung bình: %,.0f%n", avgQps);
        System.out.printf("QPS đỉnh      : %,.0f%n", peakQps);
        System.out.printf("Egress đỉnh   : %.2f Gbps%n", peakGbps);
        System.out.printf("Uplink 1 Gbps dùng: %.0f%%%n", peakGbps * 100);
    }
}

fix.code:
long photoBytes = 200 * 1024;
double peakQps = dau * viewsPerUser / 86_400.0 * peakFactor;
double peakBitsPerSec = peakQps * photoBytes * 8;          // đường truyền đo bằng bit
double peakGbps = peakBitsPerSec / 1_000_000_000;
// Egress đỉnh   : 2.84 Gbps
// Uplink 1 Gbps dùng: 284%

double targetUtilization = 0.6;                              // chừa headroom cho đỉnh ngắn
double cdnHitRatio = 0.95;                                    // giả định, kiểm lại bằng log CDN
double originGbps = peakGbps * (1 - cdnHitRatio);             // ≈ 0,14 Gbps
boolean fits = originGbps <= 1.0 * targetUtilization;
